widget.solution:
import numpy as np

def threshold(form_spread, mult=2.0):
    """mult times the formation sd (np.std, dividing by n)."""
    return mult * float(np.std(form_spread))


def first_open(spread, sd, mult=2.0):
    """(day, side) of the first |spread| > mult * sd, or None."""
    for t, s in enumerate(spread):
        if sd > 0 and abs(s) > mult * sd:
            return t, (1 if s > 0 else -1)
    return None


def units(price_long, price_short):
    """Units £1 buys of each leg."""
    return 1 / price_long, 1 / price_short
